import json
# f(x)=sum(x_i*x_i)/2; one exact full-gradient query per update.
def run(d, threshold=0.01):
    x=[1.0]*d
    initial_gap=sum(v*v for v in x)/2
    calls=0
    while sum(v*v for v in x)/2 > threshold:
        x=[v/2 for v in x]
        calls+=1
    return dict(d=d, initial_gap=initial_gap, calls=calls)
if __name__=='__main__': print(json.dumps([run(d) for d in [2,8,32,128]]))
